pub fn validate_prepared(app:&tauri::AppHandle,folder:&str,expected:Option<&str>)->Result<(),String>{if !folder.starts_with("photo-editor-restored-")||folder.len()<=22||folder.len()>80||!folder[22..].bytes().all(|b|b.is_ascii_digit()){return Err("Неверная папка восстановленного редактора.".into());}let parent=application_data_directory(app)?.canonicalize().map_err(|e|e.to_string())?;let root=parent.join(folder).canonicalize().map_err(|e|e.to_string())?;if root.parent()!=Some(parent.as_path()){return Err("Хранилище восстановления перенаправлено.".into());}if let Some(expected)=expected{let marker=root.join("restore.manifest.json");if compute_file_sha256(&marker)?!=expected{return Err("Манифест восстановления изменился после подготовки.".into());}let value:Value=serde_json::from_slice(&fs::read(marker).map_err(|e|e.to_string())?).map_err(|e|e.to_string())?;for entry in value["files"].as_array().ok_or("Нет файлов восстановления")?{let relative=entry["relativePath"].as_str().ok_or("Нет пути файла")?;if relative=="index.sqlite"{continue;}let file=safe_file(&root,relative)?;if compute_file_sha256(&file)?!=entry["sha256"].as_str().unwrap_or(""){return Err("Файл редактора изменился после подготовки восстановления.".into());}}}validate_editor(&root)}
